/**
 * The game's page: its hooks, handed to the engine's `boot()` (`@vibe/engine/boot`), which does the
 * rest -- the loading bar, the preload, the `Game`, the canvas UI, sound, the pause key, the editor's
 * keys. The game comes through `game/live.ts`, the swap boundary `vibe assets` generates; the HUD and the
 * pause menu are this project's widgets (`ui/`); the editor, the debug panel and the project's own
 * editor tools (`tools/`) its debug tools.
 *
 * **The project's assets are handed in first**: `./assets/bundle.ts`, generated by `vibe assets`, gives
 * the engine this project's globs (`useBundle`) before anything looks a key up -- so it is the first
 * import, and this is its one importer.
 *
 * **The game is handed as a function that imports it** (`game: () => import(...)`), never imported here:
 * a game module that does not load -- a syntax error under `src/game/` mid-edit -- is then boot's to
 * catch, and in studio mode (`?studio`) the editor still comes up, saying which file, with the Code card
 * and Claude to fix it (Docs/studio.md §1, "Recovery"). A static import would fail this page's module
 * graph before boot ran at all. **The UI the same** (`ui: { import: () => import('./ui/index.ts') }`): this file imports nothing
 * of the project statically but the bundle, so a bad import or a top-level throw in the HUD fails boot's import, not
 * the page.
 *
 * **Studio mode probes a change before it reloads** (Docs/studio.md §1): this file, and every module under
 * it, is evaluated for real in a hidden frame of the same origin first -- its storage, its fetches, its sound
 * are the page's. `boot()` does nothing there; any other top-level side effect of the project's own checks
 * `probing()` (`@vibe/engine/boot`) first, as `if (!probing()) localStorage.setItem(...)`.
 */
import './assets/bundle.ts';
import { boot } from '@vibe/engine/boot';
import { MrDebug } from '@vibe/engine/debug';

/** A literal in a release build (the vibe skill), so the imports it guards below are dropped there. */
const DEBUG = DEBUG_BUILD && MrDebug.on;

void boot({
  canvas: '#game',
  name: 'karty',
  title: 'karty',
  game: () => import('./game/live.ts').then((m) => m.live),
  ui: { import: () => import('./ui/index.ts') },
  // The editor, the panel and the project's own tools: each one DEBUG-gated dynamic import, so a release
  // build drops them (and debugGuard fails one that carries any of them).
  ...(DEBUG
    ? { editor: () => import('@vibe/editor'), panel: () => import('@vibe/editor/panel'), tools: () => import('./tools/index.ts') }
    : {}),
  // The tools' components, engine-only, before the world is made: behind DEBUG_BUILD, as the game's worker has them.
  ...(DEBUG_BUILD ? { components: () => import('./tools/components.ts') } : {}),
});
